     1→import Phaser from 'phaser';
     2→import Player from '../objects/Player';
     3→import Poop from '../objects/Poop';
     4→import GoldPoop from '../objects/GoldPoop';
     5→import DiamondPoop from '../objects/DiamondPoop';
     6→import TopazPoop from '../objects/TopazPoop';
     7→import RainbowPoop from '../objects/RainbowPoop';
     8→import { GameMode, Difficulty, DIFFICULTIES, type DifficultyConfig } from '../types/GameMode';
     9→import { FEVER_TIME_CONFIG } from '../config/feverTime';
    10→import { POOP_CONFIG } from '../config/poop';
    11→import { getHighScore, updateHighScore } from '../utils/localStorage';
    12→import { submitScore, getUserInitials, setUserInitials, startGameSession } from '../utils/leaderboard';
    13→import { submitSkor, type SkorSubmitResponse } from '../utils/skor';
    14→import { getSafeSelectedCharacter, getCharacterDef, getDuplicateCount, getAwakeningLevel } from '../utils/character';
    15→import { isChristmasSeason } from '../utils/seasonChecker';
    16→import type { CharacterAbility, GameSceneAPI } from '../abilities/types';
    17→import { getCharacterAbility } from '../abilities/index';
    18→import { realNow } from '../utils/realTime';
    19→
    20→export default class GameScene extends Phaser.Scene {
    21→  private player!: Player;
    22→  private poops!: Phaser.Physics.Arcade.Group;
    23→  private goldPoops!: Phaser.Physics.Arcade.Group;
    24→  private diamondPoops!: Phaser.Physics.Arcade.Group;
    25→  private topazPoops!: Phaser.Physics.Arcade.Group;
    26→  private rainbowPoops!: Phaser.Physics.Arcade.Group;
    27→  private score: number = 0;
    28→  private scoreText!: Phaser.GameObjects.Text;
    29→  private highScore: number = 0;
    30→  private highScoreText!: Phaser.GameObjects.Text;
    31→  private gameOver: boolean = false;
    32→  private spawnTimer!: Phaser.Time.TimerEvent;
    33→  private difficultyLevel: number = 2;
    34→  private bgMusic!: Phaser.Sound.BaseSound;
    35→  private gameMode: GameMode = GameMode.CLASSIC;
    36→  private difficulty: Difficulty = Difficulty.HARD;
    37→  private difficultyConfig!: DifficultyConfig;
    38→  private lastGoldPoopScore: number = 0;
    39→  private lastDiamondPoopScore: number = 0;
    40→  private lastTopazPoopScore: number = 0;
    41→  // 점수 검증용 데이터
    42→  private gameStartTime: number = 0;
    43→  private phaserStartTime: number = 0; // 씬 시작 시 Phaser 내부 시간 (재시작 시에도 정확한 delta 계산용)
    44→  private lastScoreTime: number = 0;        // realNow() 기반 점수용
    45→  private lastCheatCheckTime: number = 0;   // timeScale 감지용 (realNow 기준)
    46→  private lastPhaserCheckTime: number = 0;  // 구간 비율 감지용 Phaser 기준점
    47→  private goldCollected: number = 0;
    48→  private diamondCollected: number = 0;
    49→  private topazCollected: number = 0;
    50→  private rainbowCollected: number = 0;
    51→  // 피버 타임 관련
    52→  private isFeverTime: boolean = false; // 피버 타임 활성화 여부
    53→  private feverTimeRemaining: number = 0; // 피버 타임 남은 시간 (ms)
    54→  private feverTimeTimer?: Phaser.Time.TimerEvent; // 피버 타임 카운트다운 타이머
    55→  private feverTimeUITexts: Phaser.GameObjects.Text[] = []; // 피버 타임 UI 텍스트 (각 글자별)
    56→  private feverTimeColorOffset: number = 0; // 무지개 색상 회전 오프셋
    57→  private feverTimeColorTimer?: Phaser.Time.TimerEvent; // 색상 애니메이션 타이머
    58→  private lastFeverTimeScore: number = 0; // 마지막 피버 타임 발동 점수
    59→  private currentSpawnDelay: number = 0; // increaseDifficulty가 적용한 현재 spawn 간격
    60→  private static readonly RAINBOW_COLORS = [
    61→    '#ff0000', '#ff7f00', '#ffff00', '#00ff00', '#0000ff', '#4b0082', '#9400d3',
    62→  ];
    63→  private selectedCharId: string = 'chibi'; // 선택된 캐릭터 ID
    64→  private selectedCharGrade: string = '등급외'; // 선택된 캐릭터 등급
    65→  private charAwakeLevel: number = 0; // 각성 단계 (init에서 계산, create에서 사용)
    66→  // 서버 세션 (게임 시작 시 비동기 생성, 점수 제출 시 await)
    67→  private sessionPromise: Promise<string | null> | null = null;
    68→  // ── 캐릭터 능력 시스템 ────────────────────────────────────────────────
    69→  private ability!: CharacterAbility;
    70→  private abilityAPI!: GameSceneAPI;
    71→
    72→  constructor() {
    73→    super('GameScene');
    74→  }
    75→
    76→  init(data: { gameMode?: GameMode; difficulty?: Difficulty }) {
    77→    // 게임 재시작 시 점수 관련 변수 초기화
    78→    this.score = 0;
    79→    this.gameOver = false;
    80→    this.difficultyLevel = 2;
    81→    this.lastGoldPoopScore = 0;
    82→    this.lastDiamondPoopScore = 0;
    83→    this.lastTopazPoopScore = 0;
    84→    this.gameStartTime = realNow();
    85→    this.phaserStartTime = 0; // create()에서 설정
    86→    this.lastScoreTime = realNow();
    87→    this.goldCollected = 0;
    88→    this.diamondCollected = 0;
    89→    this.topazCollected = 0;
    90→    this.rainbowCollected = 0;
    91→    this.sessionPromise = null; // 재시작 시 이전 세션 프로미스 해제
    92→    // 피버 타임 초기화
    93→    this.isFeverTime = false;
    94→    this.feverTimeRemaining = 0;
    95→    this.lastFeverTimeScore = 0;
    96→    // 캐릭터 선택 화면에서 저장한 캐릭터를 사용
    97→    this.selectedCharId = getSafeSelectedCharacter();
    98→    const charDef        = getCharacterDef(this.selectedCharId);
    99→    const dupCount       = getDuplicateCount(this.selectedCharId);
   100→    const awakeLevel     = getAwakeningLevel(charDef.grade, dupCount);
   101→    this.selectedCharGrade = charDef.grade;
   102→    this.charAwakeLevel    = awakeLevel;
   103→    this.ability = getCharacterAbility(this.selectedCharId, awakeLevel);
   104→
   105→    // ModeSelectScene/DifficultySelectScene으로부터 게임 모드와 난이도를 받음
   106→    if (data.gameMode) {
   107→      this.gameMode = data.gameMode;
   108→      // console.log('Game Mode:', this.gameMode);
   109→    }
   110→    if (data.difficulty) {
   111→      this.difficulty = data.difficulty;
   112→      // console.log('Difficulty:', this.difficulty);
   113→      localStorage.setItem('lastPlayedDifficulty', data.difficulty);
   114→    }
   115→
   116→    // 난이도 설정 찾기
   117→    const config = DIFFICULTIES.find(d => d.difficulty === this.difficulty);
   118→    if (config) {
   119→      this.difficultyConfig = config;
   120→    } else {
   121→      // 기본값은 HARD
   122→      this.difficultyConfig = DIFFICULTIES.find(d => d.difficulty === Difficulty.HARD)!;
   123→    }
   124→    this.currentSpawnDelay = this.difficultyConfig.spawnDelay;
   125→  }
   126→
   127→  preload() {
   128→    // DifficultySelectScene에서 미리 로딩됨. 캐시에 없을 경우에만 fallback 로딩.
   129→
   130→    if (this.difficulty === Difficulty.EASY && !this.textures.exists('background2')) {
   131→      this.load.image('background2', 'assets/backgrounds/background2.webp');
   132→    } else if (this.difficulty === Difficulty.NORMAL && !this.textures.exists('background3')) {
   133→      this.load.image('background3', 'assets/backgrounds/background3.webp');
   134→    } else if (this.difficulty === Difficulty.HARD && !this.textures.exists('background')) {
   135→      this.load.image('background', 'assets/backgrounds/background.webp');
   136→    } else if (this.difficulty === Difficulty.EXTREME && !this.textures.exists('background2')) {
   137→      this.load.image('background2', 'assets/backgrounds/background2.webp');
   138→    }
   139→    if (this.difficulty === Difficulty.EXTREME && isChristmasSeason() && !this.textures.exists('xmas_background')) {
